#!/usr/bin/env python3
"""Produce and admit the complete checked Std catalog; keep the conditional boundary visible.

Usage: modular-termination-checked-std.py DAFNY Z3 OUT [--cores N]
All certificates are generated by the normal complete producer, never with skipped verification.
"""
import argparse
import json
from pathlib import Path
import shlex
import subprocess
import sys
import tomllib
import zipfile

parser = argparse.ArgumentParser(description=__doc__)
parser.add_argument('dafny')
parser.add_argument('z3')
parser.add_argument('output')
parser.add_argument('--cores', type=int, default=3)
args = parser.parse_args()
root = Path(__file__).resolve().parents[2]
std = root / 'Source/DafnyStandardLibraries'
out = Path(args.output).resolve()
out.mkdir(parents=True, exist_ok=True)
binary, solver = str(Path(args.dafny).resolve()), str(Path(args.z3).resolve())
command = ['dotnet', binary] if binary.endswith('.dll') else [binary]
rows = []


def run(name, command, expected=0, contains=()):
    result = subprocess.run(command, cwd=std, capture_output=True, text=True)
    text = result.stdout + result.stderr
    (out / (name + '.log')).write_text(text)
    accepted = result.returncode == expected and all(fragment in text for fragment in contains)
    rows.append({'case': name, 'exit': result.returncode, 'accepted': accepted})
    print(name + ': ' + ('PASS' if accepted else 'FAIL'), flush=True)
    if not accepted:
        print(text, flush=True)
        raise RuntimeError(name)
    return text


try:
    run('produce', [sys.executable, str(std / 'modular-termination/overlay/build-checked.py'),
        '--dafny', shlex.join(command), '--solver', solver, '--cores', str(args.cores)])
    common = std / 'binaries/DafnyStandardLibraries-checked.doo'
    options = ['--standard-libraries:false', '--solver-path', solver,
        '--type-system-refresh', '--general-traits=datatype', '--general-newtypes',
        '--reads-clauses-on-methods', '--enforce-determinism', '--track-print-effects',
        '--cores', str(args.cores), '--resource-limit', '16000000', '--use-basename-for-filename']
    ghost = '--modular-termination-trust:standard-library'
    runtime = '--modular-termination-runtime-trust:standard-library'
    family = root / 'Source/IntegrationTests/TestFiles/LitTests/LitTest/git-issues/Inputs/github-issue-211-checked-std-five-families.dfy'
    source = family.read_text()
    client = out / 'client.dfy'
    client.write_text(source)
    base = command + ['verify'] + options + ['--library:' + str(common), str(client)]
    run('common-no-ghost-opt-in', base, expected=1, contains=[ghost])
    run('common-client', base + [ghost])
    client.write_text(source.replace('// CONTROL', 'hide *; assert false;'))
    text = run('common-false', base + [ghost], expected=4,
        contains=['Error: assertion might not hold', '1 error'])
    assert text.count('Error: assertion might not hold') == 1
    assert 'out of resource' not in text and 'timed out' not in text
    client.write_text("""module Client {
  import Std.FileIOInternalExterns
  import Std.ActionsExterns
  method Use() {
    var failed, bytes, message := FileIOInternalExterns.INTERNAL_ReadBytesFromFile("unused");
    var producer, proof := ActionsExterns.MakeSetReader({7});
    assert proof.Valid();
    assert proof.Producer() == producer;
    assert producer.allowance <= proof.allowance;
    proof.ProducesSet([]);
    // CONTROL
  }
}
""")
    original = client.read_text()
    for target in ['notarget', 'cs', 'java', 'js', 'go', 'py']:
        bundle = std / ('binaries/DafnyStandardLibraries-checked-' + target + '.doo')
        with zipfile.ZipFile(bundle) as archive:
            record = tomllib.loads(archive.read('manifest.toml').decode())['modular_termination']
        premises = record['runtime_premises']
        assert premises and record['runtime_trust_list'] == 'standard-library'
        names = [entry['id'] for entry in premises]
        client.write_text(original)
        base = command + ['verify'] + options + [ghost, '--library:' + str(common),
            '--library:' + str(bundle), str(client)]
        run(target + '-no-runtime-opt-in', base, expected=1, contains=[runtime])
        run(target + '-client', base + [runtime], contains=names + ['including termination'])
        client.write_text(original.replace('// CONTROL', 'assert false;'))
        text = run(target + '-false', base + [runtime], expected=4,
            contains=['Error: assertion might not hold', '1 error'] + names)
        assert text.count('Error: assertion might not hold') == 1
        assert 'out of resource' not in text and 'timed out' not in text
        audit_options = options.copy()
        for flag in ['--cores', '--resource-limit']:
            offset = audit_options.index(flag)
            del audit_options[offset:offset + 2]
        run(target + '-audit', command + ['audit'] + audit_options + [ghost, runtime,
            '--library:' + str(common), '--library:' + str(bundle), str(client)], contains=names)
finally:
    (out / 'results.json').write_text(json.dumps(rows, indent=2) + '\n')
    (out / 'summary.md').write_text('# Checked standard-library release gates\n\n' +
        '\n'.join('- ' + row['case'] + ': ' + ('PASS' if row['accepted'] else 'FAIL') for row in rows) + '\n')
